CREATE TABLE IF NOT EXISTS credentials(user_id TEXT PRIMARY KEY, salt TEXT NOT NULL, hash TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)); CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)); CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);